<?php include "../includes/auth.php"; include "../config/connection.php"; include "../includes/header.php"; $r=mysqli_query($conn,"SELECT c.id,c.name,COUNT(o.id) orders_count FROM customers c LEFT JOIN orders o ON c.id=o.customer_id GROUP BY c.id,c.name ORDER BY c.name"); ?>
<h2>Number Of Orders For Each Customer</h2><div class="table-responsive"><table class="table table-bordered table-striped bg-white mt-3"><thead class="table-dark"><tr><th>Customer ID</th><th>Customer Name</th><th>Orders Count</th></tr></thead><tbody><?php while($x=mysqli_fetch_assoc($r)): ?><tr><td><?php echo $x['id']; ?></td><td><?php echo htmlspecialchars($x['name']); ?></td><td><?php echo $x['orders_count']; ?></td></tr><?php endwhile; ?></tbody></table></div><p class="text-muted">Ahmed has 5 orders and Tariq has 9 orders in the sample data.</p><a href="../index.php" class="btn btn-secondary">Back Home</a><?php include "../includes/footer.php"; ?>